export const m78Hash=(v:unknown)=>new Bun.CryptoHasher('sha256').update(m78CanonicalJson(v)).digest('hex')
export const m78BytesHash=(v:string)=>new Bun.CryptoHasher('sha256').update(v).digest('hex')
const bytes=(v:string)=>new TextEncoder().encode(v).length,same=(a:unknown,b:unknown)=>m78CanonicalJson(a)===m78CanonicalJson(b),last=<T>(a:T[])=>a[a.length-1],flags={synthetic:true as const,scope1Completeness:'incomplete' as const,corporateCompleteness:'incomplete' as const,releaseEligible:false as const,assurance:'none' as const,review:null}
const fail=():never=>{throw Error('Stored Scope 1 records could not be verified.')},verify=(v:unknown)=>{if(!v)fail()},iso=(v:string)=>new Date(v).toISOString(),changed=():never=>{throw Object.assign(Error('Scope 1 dependencies changed.'),{code:'23505'})}
export function m78CheckResponseCapacity(value:unknown){if(bytes(m78CanonicalJson(value))>M78_MAX_RESPONSE_BYTES)throw Object.assign(Error('Scope 1 register response capacity reached.'),{code:'54000',capacityKind:'register_response'})}
async function lock(tx:WorkspaceSql,companyId:string,writing:boolean){const allowed=(await tx.query<{allowed:boolean}>('select neuvetra.m78_lock($1,$2)allowed',[companyId,writing])).rows[0]?.allowed===true;if(!allowed&&writing)throw Object.assign(Error('Forbidden.'),{code:'42501'});return allowed}
async function upstream(tx:WorkspaceSql,companyId:string,a:M78Authorities){const corporate=await readCorporateInventory(tx,companyId);if(!corporate)return null;const gas=await readStationaryGas(tx,companyId,a.gas),mobile=await readMobileDiesel(tx,companyId,a.mobile),diesel=await readStationaryDiesel(tx,companyId,a.diesel),fleet=await readControlledFleet(tx,companyId,a.mobile),stationary=await readStationaryEquipment(tx,companyId,{gas:a.gas,diesel:a.diesel}),fugitive=await readFugitive(tx,companyId,a.fugitive);verify(gas&&mobile&&diesel&&fleet&&stationary&&fugitive);return {corporate,gas:gas!,mobile:mobile!,diesel:diesel!,fleet:fleet!,stationary:stationary!,fugitive:fugitive!}}
type Upstream=NonNullable<Awaited<ReturnType<typeof upstream>>>
function currentProof(u:Upstream,process:M78Proof['process'],policy:M78Policy|null):M78Proof{const c=u.corporate.versions.find(v=>v.id===u.corporate.headVersionId)??fail(),fv=u.fleet.versions.find(v=>v.id===u.fleet.headVersionId)??null,sv=u.stationary.versions.find(v=>v.id===u.stationary.headVersionId)??null,pv=u.fugitive.population.versions.find(v=>v.id===u.fugitive.population.headVersionId)??null;const boundIds=[fv?.activity.coverageVersionId,sv?.activity.coverageVersionId,pv?.activity.coverageVersionId,process?.version.activity.binding.coverageVersionId].filter((x):x is string=>Boolean(x));return {priorVersions:[],coverageVersion:c,boundCoverageVersions:[...new Set(boundIds)].filter(id=>id!==c.id).sort().map(id=>u.corporate.versions.find(v=>v.id===id)??fail()),sourceVersions:[...u.gas.worksheets.map(w=>({family:'natural_gas' as const,version:w.versions.find(v=>v.id===w.headVersionId)!})),...u.diesel.worksheets.map(w=>({family:'stationary_diesel' as const,version:w.versions.find(v=>v.id===w.headVersionId)!})),...u.mobile.worksheets.map(w=>({family:'mobile_diesel' as const,version:w.versions.find(v=>v.id===w.headVersionId)!})),...u.fugitive.worksheets.map(w=>({family:'fugitive' as const,version:w.versions.find(v=>v.id===w.headVersionId)!}))].sort((a,b)=>a.version.id<b.version.id?-1:1),fleet:{version:fv,review:u.fleet.reviews.find(r=>r.versionId===fv?.id&&r.dependencies.dependencySha256===u.fleet.reconciliation.dependencySha256)??null,reconciliation:u.fleet.reconciliation},stationary:{version:sv,review:u.stationary.reviews.find(r=>r.versionId===sv?.id&&r.dependencies.dependencySha256===u.stationary.reconciliation.dependencySha256)??null,reconciliation:u.stationary.reconciliation},fugitive:{version:pv?{...pv,review:null}:null,review:pv?.review?.dependencies?.dependencySha256===u.fugitive.reconciliation.dependencySha256?pv.review:null,reconciliation:u.fugitive.reconciliation},process,policy}}
function checkReview(stored:any,actual:any,capturedAt:string){if(stored===null){verify(!actual||actual.reviewedAt>=capturedAt);return null}verify(actual&&same(stored,actual)&&actual.reviewedAt<=capturedAt);return stored}
function verifyProof(p:M78Proof,u:Upstream,versions:M78Version[],reviews:M78Review[],capturedAt:string,policy:M78Policy|null,proofs:Map<string,M78Proof>){m78Keys(p,['priorVersions','coverageVersion','boundCoverageVersions','sourceVersions','fleet','stationary','fugitive','process','policy']);const c=u.corporate.versions.find(c=>c.id===p.coverageVersion.id)??fail();verify(same({...c,review:null},{...p.coverageVersion,review:null})&&c.createdAt<=capturedAt);checkReview(p.coverageVersion.review,c.review,capturedAt);const requiredIds=[p.fleet.version?.activity.coverageVersionId,p.stationary.version?.activity.coverageVersionId,(p.fugitive.version?.activity as any)?.coverageVersionId,p.process?.version.activity.binding.coverageVersionId].filter(x=>x&&x!==c.id);verify(same([...new Set(requiredIds)].sort(),p.boundCoverageVersions.map(v=>v.id).sort()));for(const b of p.boundCoverageVersions){const actual=u.corporate.versions.find(v=>v.id===b.id)??fail();verify(same({...actual,review:null},{...b,review:null})&&actual.createdAt<=capturedAt);checkReview(b.review,actual.review,capturedAt)}const pools={natural_gas:u.gas.worksheets.flatMap(w=>w.versions),stationary_diesel:u.diesel.worksheets.flatMap(w=>w.versions),mobile_diesel:u.mobile.worksheets.flatMap(w=>w.versions),fugitive:u.fugitive.worksheets.flatMap(w=>w.versions)};verify(new Set(p.sourceVersions.map(x=>x.version.id)).size===p.sourceVersions.length);for(const x of p.sourceVersions){m78Keys(x,['family','version']);const actual=pools[x.family]?.find(v=>v.id===x.version.id)??fail();verify(same({...actual,review:null},{...x.version,review:null})&&actual.createdAt<=capturedAt);checkReview(x.version.review,actual.review,capturedAt)}
 const fleet=p.fleet.version?u.fleet.versions.find(v=>v.id===p.fleet.version!.id)??fail():null,stationary=p.stationary.version?u.stationary.versions.find(v=>v.id===p.stationary.version!.id)??fail():null,fugitive=p.fugitive.version?u.fugitive.population.versions.find(v=>v.id===p.fugitive.version!.id)??fail():null;verify((!fleet||fleet.createdAt<=capturedAt)&&(!stationary||stationary.createdAt<=capturedAt)&&(!fugitive||fugitive.createdAt<=capturedAt)&&same(fleet,p.fleet.version)&&same(stationary,p.stationary.version)&&same(fugitive?{...fugitive,review:null}:null,p.fugitive.version));checkReview(p.fleet.review,u.fleet.reviews.find(r=>r.id===p.fleet.review?.id)??u.fleet.reviews.find(r=>r.versionId===fleet?.id&&r.dependencies.dependencySha256===p.fleet.reconciliation.dependencySha256)??null,capturedAt);checkReview(p.stationary.review,u.stationary.reviews.find(r=>r.id===p.stationary.review?.id)??u.stationary.reviews.find(r=>r.versionId===stationary?.id&&r.dependencies.dependencySha256===p.stationary.reconciliation.dependencySha256)??null,capturedAt);checkReview(p.fugitive.review,fugitive?.review?.dependencies?.dependencySha256===p.fugitive.reconciliation.dependencySha256?fugitive.review:null,capturedAt);
 const mobile=p.sourceVersions.filter(x=>x.family==='mobile_diesel').map(x=>x.version as any),gas=p.sourceVersions.filter(x=>x.family==='natural_gas').map(x=>x.version as any),diesel=p.sourceVersions.filter(x=>x.family==='stationary_diesel').map(x=>x.version as any),fugs=p.sourceVersions.filter(x=>x.family==='fugitive').map(x=>x.version as any);verify(same(p.fleet.reconciliation,deriveM75Reconciliation(c.companyId,p.coverageVersion,mobile,fleet,p.fleet.review?[p.fleet.review]:[],m78Hash))&&same(p.stationary.reconciliation,deriveM76Reconciliation(c.companyId,p.coverageVersion,gas,diesel,stationary,p.stationary.review?[p.stationary.review]:[],m78Hash))&&same(p.fugitive.reconciliation,deriveM77Reconciliation(c.companyId,p.coverageVersion,fugs,fugitive,p.fugitive.review?[p.fugitive.review]:[],m78Hash)));if(p.process){m78Keys(p.process,['version','review','proof']);verify(p.process.proof.process===null);const v=versions.find(v=>v.id===p.process!.version.id)??fail();verify(same({...v,review:null},p.process.version)&&v.createdAt<=capturedAt&&same(p.process.proof,proofs.get(v.id)));checkReview(p.process.review,reviews.find(r=>r.versionId===v.id)??null,capturedAt)}if(p.policy)verify(policy&&same(p.policy,policy));verify(bytes(m78CanonicalJson(p))<=M78_MAX_PROOF_BYTES)}
type Row={id:string;company_id:string;stream_id:string;family:M78Family;version_id?:string;version?:number;revision?:number;payload:any;proof:M78Proof;input_sha256?:string;content_sha256?:string;version_sha256?:string;export_text?:string;created_by?:string;created_at?:string;reviewed_by?:string;reviewed_at?:string;decision_sha256?:string;report_sha256?:string;statement_text?:string;statement_sha256?:string}
async function state(tx:WorkspaceSql,companyId:string,authorities:M78Authorities,policy:M78Policy|null){if(!await lock(tx,companyId,false))return null;const u=await upstream(tx,companyId,authorities);return u?verifiedState(tx,companyId,policy,u):null}
// Private graph input: only state() or the locked write closure can supply it.
async function verifiedState(tx:WorkspaceSql,companyId:string,policy:M78Policy|null,u:Upstream){const result=(await tx.query<{heads:Row[];versions:Row[];reviews:Row[];reports:Row[];statements:Row[];requests:any[];audits:any[];discoveries:any[]}>(`select coalesce((select jsonb_agg(x order by family)from neuvetra.scope1_heads x where company_id=$1),'[]')heads,coalesce((select jsonb_agg(x order by created_at,id)from neuvetra.scope1_versions x where company_id=$1),'[]')versions,coalesce((select jsonb_agg(x order by reviewed_at,id)from neuvetra.scope1_reviews x where company_id=$1),'[]')reviews,coalesce((select jsonb_agg(x order by created_at,id)from neuvetra.scope1_reports x where company_id=$1),'[]')reports,coalesce((select jsonb_agg(x)from neuvetra.scope1_statements x where company_id=$1),'[]')statements,coalesce((select jsonb_agg(x)from neuvetra.scope1_requests x where company_id=$1),'[]')requests,coalesce((select jsonb_agg(x order by sequence)from neuvetra.scope1_audit x where company_id=$1),'[]')audits,coalesce((select jsonb_agg(x)from neuvetra.scope1_process_discoveries x where company_id=$1),'[]')discoveries`,[companyId])).rows[0]!;const versions:M78Version[]=[],reviews:M78Review[]=[],reports:M78Report[]=[],proofs=new Map<string,M78Proof>();verify(result.heads.length<=2&&result.versions.length<=40&&result.reports.length<=80&&result.audits.length===result.versions.length+result.reviews.length+result.reports.length&&result.requests.length===result.audits.length);
 const audit=(kind:string,id:string,digest:string,actor:string,at:string)=>{const list=result.audits.filter(a=>a.record_id===id&&a.kind===kind);verify(list.length===1&&list[0].company_id===companyId&&list[0].record_sha256===digest&&list[0].actor_id===actor&&iso(list[0].created_at)===at);return Number(list[0].sequence)};
